
SET NOCOUNT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET ARITHABORT ON;
SET CONCAT_NULL_YIELDS_NULL ON;
GO

/* 1. 建数据库。已经有了就不重复建 */
IF DB_ID(N'LXShopping') IS NULL
BEGIN
    PRINT N'>> 正在创建数据库 LXShopping ...';
    CREATE DATABASE [LXShopping];
END
ELSE
BEGIN
    PRINT N'>> 数据库 LXShopping 已存在，即将重建其中的表。';
END
GO

USE [LXShopping];
GO

/* 2. 先把旧表删掉。顺序要跟外键反过来，不然删不动。
   先删是为了这个脚本可以反复执行，不会报"表已存在" */
IF OBJECT_ID(N'dbo.OrderDetail', N'U')        IS NOT NULL DROP TABLE [dbo].[OrderDetail];
IF OBJECT_ID(N'dbo.OrderHeader', N'U')        IS NOT NULL DROP TABLE [dbo].[OrderHeader];
IF OBJECT_ID(N'dbo.Cart', N'U')               IS NOT NULL DROP TABLE [dbo].[Cart];
IF OBJECT_ID(N'dbo.Product', N'U')            IS NOT NULL DROP TABLE [dbo].[Product];
IF OBJECT_ID(N'dbo.ProductCategory', N'U')    IS NOT NULL DROP TABLE [dbo].[ProductCategory];
IF OBJECT_ID(N'dbo.MemberAddress', N'U')      IS NOT NULL DROP TABLE [dbo].[MemberAddress];
IF OBJECT_ID(N'dbo.Member', N'U')             IS NOT NULL DROP TABLE [dbo].[Member];
IF OBJECT_ID(N'dbo.Admin', N'U')              IS NOT NULL DROP TABLE [dbo].[Admin];
IF OBJECT_ID(N'dbo.__MigrationHistory', N'U') IS NOT NULL DROP TABLE [dbo].[__MigrationHistory];
GO

/* 3. 建表 */

/* 3.1 管理员表 */
CREATE TABLE [dbo].[Admin] (
    [Id]        int           IDENTITY(1,1) NOT NULL,
    [AdminName] nvarchar(40)  NOT NULL,
    [Pwd]       nvarchar(40)  NOT NULL,
    [ChinaName] nvarchar(20)  NOT NULL,
    [Role]      nvarchar(20)  NULL,
    CONSTRAINT [PK_dbo.Admin] PRIMARY KEY CLUSTERED ([Id])
);
GO

/* 3.2 会员表 */
CREATE TABLE [dbo].[Member] (
    [Id]            int            IDENTITY(1,1) NOT NULL,
    [Email]         nvarchar(250)  NOT NULL,
    [Password]      nvarchar(40)   NOT NULL,
    [Name]          nvarchar(5)    NOT NULL,
    [Nickname]      nvarchar(10)   NOT NULL,
    [RegisterOn]    datetime       NOT NULL,
    [ImageData]     varbinary(max) NULL,
    [ImageMimeType] nvarchar(max)  NULL,
    [AuthCode]      nvarchar(36)   NULL,
    CONSTRAINT [PK_dbo.Member] PRIMARY KEY CLUSTERED ([Id])
);
GO

/* 3.3 收货地址表 */
CREATE TABLE [dbo].[MemberAddress] (
    [Id]             int           IDENTITY(1,1) NOT NULL,
    [ContactName]    nvarchar(40)  NOT NULL,
    [ContactPhoneNo] nvarchar(25)  NOT NULL,
    [ContactAddress] nvarchar(200) NOT NULL,
    [Member_Id]      int           NOT NULL,
    CONSTRAINT [PK_dbo.MemberAddress] PRIMARY KEY CLUSTERED ([Id])
);
GO

/* 3.4 商品分类表 */
CREATE TABLE [dbo].[ProductCategory] (
    [Id]   int          IDENTITY(1,1) NOT NULL,
    [Name] nvarchar(20) NOT NULL,
    [Icon] nvarchar(20) NULL,
    [Sort] int          NOT NULL,
    CONSTRAINT [PK_dbo.ProductCategory] PRIMARY KEY CLUSTERED ([Id])
);
GO

/* 3.5 商品表 */
CREATE TABLE [dbo].[Product] (
    [Id]                 int            IDENTITY(1,1) NOT NULL,
    [Name]               nvarchar(60)   NOT NULL,
    [ImageData]          varbinary(max) NULL,
    [ImageMimeType]      nvarchar(max)  NULL,
    [Amount]             int            NOT NULL,
    [Description]        nvarchar(250)  NOT NULL,
    [Made]               nvarchar(60)   NOT NULL,
    [Price]              decimal(18,2)  NOT NULL,
    [PublishOn]          datetime       NULL,
    [Sales]              int            NOT NULL,
    [IsPublished]        bit            NOT NULL,
    [OriginalPrice]      decimal(18,2)  NULL,
    [ProductCategory_Id] int            NOT NULL,
    CONSTRAINT [PK_dbo.Product] PRIMARY KEY CLUSTERED ([Id])
);
GO

/* 3.6 购物车表 */
CREATE TABLE [dbo].[Cart] (
    [Id]         int IDENTITY(1,1) NOT NULL,
    [Amount]     int NOT NULL,
    [Member_Id]  int NOT NULL,
    [Product_Id] int NOT NULL,
    CONSTRAINT [PK_dbo.Cart] PRIMARY KEY CLUSTERED ([Id])
);
GO

/* 3.7 订单表 */
CREATE TABLE [dbo].[OrderHeader] (
    [Id]               int           IDENTITY(1,1) NOT NULL,
    [OrderNo]          nvarchar(30)  NULL,
    [TotalPrice]       decimal(18,2) NOT NULL,
    [Memo]             nvarchar(200) NULL,
    [BuyOn]            datetime      NOT NULL,
    [PayMethod]        nvarchar(20)  NULL,
    [MemberAddress_Id] int           NOT NULL,
    CONSTRAINT [PK_dbo.OrderHeader] PRIMARY KEY CLUSTERED ([Id])
);
GO

/* 3.8 订单明细表 */
CREATE TABLE [dbo].[OrderDetail] (
    [Id]             int           IDENTITY(1,1) NOT NULL,
    [UnitPrice]      decimal(18,2) NOT NULL,
    [Price]          decimal(18,2) NOT NULL,
    [Amount]         int           NOT NULL,
    [Shipmentnumber] nvarchar(40)  NULL,
    [ProductName]    nvarchar(60)  NULL,
    [OrderHeader_Id] int           NOT NULL,
    [Product_Id]     int           NOT NULL,
    CONSTRAINT [PK_dbo.OrderDetail] PRIMARY KEY CLUSTERED ([Id])
);
GO

/* 3.9 EF 自己用的迁移记录表，别删 */
CREATE TABLE [dbo].[__MigrationHistory] (
    [MigrationId]    nvarchar(150)  NOT NULL,
    [ContextKey]     nvarchar(300)  NOT NULL,
    [Model]          varbinary(max) NOT NULL,
    [ProductVersion] nvarchar(32)   NOT NULL,
    CONSTRAINT [PK_dbo.__MigrationHistory] PRIMARY KEY CLUSTERED ([MigrationId], [ContextKey])
);
GO

/* 4. 加外键，跟 EF 模型里配的关系保持一致 */
ALTER TABLE [dbo].[MemberAddress] ADD CONSTRAINT [FK_dbo.MemberAddress_dbo.Member_Member_Id]
    FOREIGN KEY ([Member_Id]) REFERENCES [dbo].[Member] ([Id]) ON DELETE NO ACTION;
GO
ALTER TABLE [dbo].[Product] ADD CONSTRAINT [FK_dbo.Product_dbo.ProductCategory_ProductCategory_Id]
    FOREIGN KEY ([ProductCategory_Id]) REFERENCES [dbo].[ProductCategory] ([Id]) ON DELETE NO ACTION;
GO
ALTER TABLE [dbo].[Cart] ADD CONSTRAINT [FK_dbo.Cart_dbo.Member_Member_Id]
    FOREIGN KEY ([Member_Id]) REFERENCES [dbo].[Member] ([Id]) ON DELETE NO ACTION;
GO
ALTER TABLE [dbo].[Cart] ADD CONSTRAINT [FK_dbo.Cart_dbo.Product_Product_Id]
    FOREIGN KEY ([Product_Id]) REFERENCES [dbo].[Product] ([Id]) ON DELETE NO ACTION;
GO
ALTER TABLE [dbo].[OrderHeader] ADD CONSTRAINT [FK_dbo.OrderHeader_dbo.MemberAddress_MemberAddress_Id]
    FOREIGN KEY ([MemberAddress_Id]) REFERENCES [dbo].[MemberAddress] ([Id]) ON DELETE NO ACTION;
GO
ALTER TABLE [dbo].[OrderDetail] ADD CONSTRAINT [FK_dbo.OrderDetail_dbo.OrderHeader_OrderHeader_Id]
    FOREIGN KEY ([OrderHeader_Id]) REFERENCES [dbo].[OrderHeader] ([Id]) ON DELETE CASCADE;
GO
ALTER TABLE [dbo].[OrderDetail] ADD CONSTRAINT [FK_dbo.OrderDetail_dbo.Product_Product_Id]
    FOREIGN KEY ([Product_Id]) REFERENCES [dbo].[Product] ([Id]) ON DELETE NO ACTION;
GO

/* 5. 加索引。这几个是 EF 给每个外键自动建的那种 */
CREATE INDEX [IX_Member_Id]          ON [dbo].[MemberAddress] ([Member_Id]);
GO
CREATE INDEX [IX_Member_Id]          ON [dbo].[Cart] ([Member_Id]);
GO
CREATE INDEX [IX_Product_Id]         ON [dbo].[Cart] ([Product_Id]);
GO
CREATE INDEX [IX_ProductCategory_Id] ON [dbo].[Product] ([ProductCategory_Id]);
GO
CREATE INDEX [IX_MemberAddress_Id]   ON [dbo].[OrderHeader] ([MemberAddress_Id]);
GO
CREATE INDEX [IX_OrderHeader_Id]     ON [dbo].[OrderDetail] ([OrderHeader_Id]);
GO
CREATE INDEX [IX_Product_Id]         ON [dbo].[OrderDetail] ([Product_Id]);
GO

